          return{resources:[{type:"meal",id:mealId,revision:1},{type:"consumption_record",id:recordId,revision:1},{type:"purchase",id:purchaseId,revision:1},...itemIds.map(id=>({type:"intake_item" as const,id,revision:1})),...purchaseItemIds.map(id=>({type:"purchase_item" as const,id,revision:1})),...(moneyId?[{type:"money_entry" as const,id:moneyId,revision:1}]:[]),...(visitId?[{type:"visit" as const,id:visitId,revision:1}]:[]),...sourceIds.map(id=>({type:"source" as const,id,revision:1}))],actualValues:{meal_id:mealId,consumption_record_id:recordId,purchase_id:purchaseId,consumed_items:consumedItems.length,purchased_items:input.purchased_items.length,...(moneyId?{money_entry_id:moneyId,payment_method:input.payment?.payment_method??null}:{payment_known:false}),...(visitId?{visit_id:visitId}:{})}};
